import {canonicalSha256} from '../core/canonical-json.mjs';
export function mineGitHistoryPatterns({commits=[]}={}){const groups=new Map();for(const commit of commits){const key=[...(commit.files??[])].sort().join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(commit);}const results=[];for(const [key,items] of groups){const successful=items.filter(x=>x.outcome==='success');if(successful.length<2)continue;const payload={kind:'git-history-pattern',maturity:'observed',files:key.split('|'),recurrence:items.length,successful:successful.length,pattern:`Changes to ${key} repeatedly require paired implementation and test updates`,mechanism:'recurring-file-cochange',sourceCommitIds:items.map(x=>x.id).sort()};results.push(Object.freeze({...payload,instinctSha256:canonicalSha256(payload)}));}return results.sort((a,b)=>a.instinctSha256.localeCompare(b.instinctSha256));}
